import {
    Check,
    Copy,
    Wallet
} from 'lucide-react';

import { Button } from '@/Components/UI/Button';
import { usePermission } from '@/Hooks/usePermission';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';
import React from 'react';
import z from 'zod';

export function useUserBalanceConfig(props: CrudPageProps): CrudConfig {

    const modelProperty = props?.modelProperty;
    const routePrefix = modelProperty?.routePrefix;

    const baseBreadcrumbs = [
        { label: 'Dashboard', href: route('backend.dashboard') },
        { label: 'User Wallets', href: route(`${routePrefix}.index`) },
    ];

    const { t } = useTranslations();
    const { can } = usePermission();

    return {

        resource: 'user_balance',
        resourcePlural: 'user_balances',
        title: 'User Wallets',
        description: 'Manage user wallet balances',

        formDisplayMode: 'modal',
        viewDisplayMode: 'page',
        tableAction: false,

        routes: {
            index: `${routePrefix}.index`,
            store: `${routePrefix}.handle`,
        },

        formValidationRules: {
            amount: z.string().min(0.00000001, 'Amount must be greater than 0'),
            type: z.enum(['deposit', 'withdraw']),
            note: z.string().optional(),
        },

        table: {
            selectable: false,
            searchable: true,
            sortable: true,
            serializable: true,
            actions: false,

            searchPlaceholder: 'Search wallet address, user...',

            columns: [

                {
                    key: 'user',
                    label: 'User',
                    render: (row: any) => (
                        <div className="flex flex-col">
                            <span className="font-medium">{row?.user?.name}</span>
                            <span className="text-xs text-gray-500">{row?.user?.email}</span>
                        </div>
                    )
                },

                {
                    key: 'wallet_address',
                    label: 'Wallet Address',
                    render: (row: any) => {

                        const [copied, setCopied] = React.useState(false);

                        const copyToClipboard = async () => {
                            try {
                                await navigator.clipboard.writeText(row.wallet_address);
                                setCopied(true);
                                setTimeout(() => setCopied(false), 1500);
                            } catch (err) {
                                console.error(err);
                            }
                        };

                        return (
                            <div className="flex items-center justify-between gap-2">

                                {/* wallet text */}
                                <code className="text-xs bg-muted px-2 py-1 rounded">
                                    {row.wallet_address}
                                </code>

                                {/* copy button */}
                                <button
                                    onClick={copyToClipboard}
                                    className="p-1 rounded hover:bg-gray-200 dark:hover:bg-gray-700"
                                >
                                    {copied ? (
                                        <Check className="w-4 h-4 text-green-600" />
                                    ) : (
                                        <Copy className="w-4 h-4" />
                                    )}
                                </button>

                            </div>
                        );
                    }
                },

                {
                    key: 'available_balance',
                    label: 'Balance',
                    render: (row: any) => (
                        <div className="flex items-center gap-1 font-semibold">
                            <Wallet className="w-4 h-4 text-blue-600" />
                            {row.formatted_balance}
                        </div>
                    )
                },

                {
                    key: 'actions',
                    label: 'Actions',
                    render: (row: any) => {

                        const openWalletModal = (type: 'deposit' | 'withdraw') => {
                            window.dispatchEvent(
                                new CustomEvent('open-wallet-modal', {
                                    detail: {
                                        user_id: row.user.id,
                                        type,
                                        user: row.user
                                    }
                                })
                            );
                        };

                        return (


                            can('wallet.handle') ? (

                                < Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => openWalletModal('deposit')
                                    }
                                    className="flex items-center gap-2"
                                >
                                    <Wallet className="w-4 h-4" />
                                    {t('Handle Balance')}
                                </Button>

                            ) : '---'



                        );
                    }
                },
                {
                    key: 'created_at',
                    label: 'Created At',
                    renderType: 'date',
                }
            ]
        },

        form: {
            title: {
                create: 'Wallet Transaction',
                edit: 'Wallet Transaction',
            },
            submitButtonText: {
                create: 'Submit',
                edit: 'Update',
            },

            fields: [

                {
                    name: 'amount',
                    label: 'Amount',
                    type: 'number',
                    placeholder: 'Enter amount...',
                    required: true,
                    section: 'basic',
                },

                {
                    name: 'type',
                    label: 'Type',
                    type: 'select',
                    required: true,
                    options: [
                        { value: 'deposit', label: 'Add Balance' },
                        { value: 'withdraw', label: 'Subtract Balance' },
                    ],
                    section: 'basic',
                },

                {
                    name: 'note',
                    label: 'Note',
                    type: 'text',
                    placeholder: 'Enter note...',
                    required: false,
                    section: 'basic',
                }
            ]
        },

        breadcrumbs: {
            index: baseBreadcrumbs,
            create: [
                ...baseBreadcrumbs,
                { label: 'Create', href: null, active: true }
            ],
        },

        filters: {
            searchFields: ['wallet address', 'username', 'email', 'name', 'phone'],
            filterFields: [],
        },


        permissions: {
            actions: {
                create: 'wallet.update',
                edit: 'wallet.update',
                view: 'wallet.view',
                delete: 'wallet.delete',
                handle: 'wallet.handle',
            },
        },

        labels: {
            singular: 'Wallet',
            plural: 'Wallets',
            key: 'wallet',
        }
    };
}